export const workspaceCategories = [
  { id: 'start', title: 'Getting started', description: 'Find your way around and set up your first workspace.' },
  { id: 'content', title: 'Content planning', description: 'Create, organize and prepare content for your team.' },
  { id: 'review', title: 'Reviews & approvals', description: 'Move work from private team review to client approval.' },
  { id: 'knowledge', title: 'Business Knowledge', description: 'Give AI the facts and personality behind your brand.' },
  { id: 'ai', title: 'AI Studio', description: 'Brief, generate and refine content before it reaches the calendar.' },
  { id: 'research', title: 'Randy', description: 'Chat about your business, research ideas and build your knowledge.' },
  { id: 'channels', title: 'Social connections', description: 'Connect the right accounts and understand their capabilities.' },
  { id: 'publishing', title: 'Publishing', description: 'Control scheduling, authorizations and publishing status.' },
  { id: 'inbox', title: 'Inbox & AI replies', description: 'Reply across channels and bring in a person when needed.' },
  { id: 'leads', title: 'Leads', description: 'Capture contacts, qualify opportunities and follow up.' },
  { id: 'analytics', title: 'Analytics & Reporting', description: 'Read real performance data and act on useful insights.' },
  { id: 'people', title: 'People & permissions', description: 'Invite teammates and give each person appropriate access.' },
  { id: 'settings', title: 'Client access & settings', description: 'Share the client portal and manage your workspace safely.' },
] as const;
export type WorkspaceHelpCategory = typeof workspaceCategories[number]['id'];
export type WorkspaceGuide = { id: string; category: WorkspaceHelpCategory; title: string; description: string; access: string; steps: string[]; outcome: string; note?: string; troubleshooting?: string[]; related: string[] };
export const workspaceGuides: WorkspaceGuide[] = [
  { id:'create-workspace', category:'start', title:'Create your first Marketing Workspace', description:'Give each business or client a dedicated home for content, knowledge and conversations.', access:'An account with workspace allowance available.', steps:['Sign in to Showwork and open Marketing Workspaces from your dashboard.','Use the new-workspace form and enter the business or client name.','Select Create workspace and wait for the new workspace to open. A private client password is created automatically.','Start with Knowledge to add business information, then Channels to connect social accounts.','Invite your team from People when you are ready to collaborate.'], outcome:'A separate workspace for this business, with its own content, sources, access and connections.', troubleshooting:['If creation is unavailable, check your workspace allowance and subscription on Billing.'], related:['navigate-workspace','upload-knowledge','invite-teammate'] },
  { id:'navigate-workspace', category:'start', title:'Find tools and navigate the workspace', description:'Use desktop navigation, mobile menus and the overview without losing your place.', access:'Any workspace member; available sections depend on permissions.', steps:['Open a workspace and use Overview to see planning activity, upcoming work and shortcuts.','On desktop, select a section from the left menu. Use its chevron control to collapse the menu to icons or expand it again.','On mobile, use Home, Content, Inbox and AI Studio in the bottom menu. Open More for the remaining sections available to you.','Use the blue workspace header to open Client view or Settings when available.','Use Help & guides from the menu to open these instructions in a separate tab.'], outcome:'You can reach the tools your role permits and keep the workspace open while reading help.', note:'Switching sections preserves visited panels. Save edits before leaving the website or refreshing the browser.', related:['content-stages','team-permissions','client-portal'] },
  { id:'create-post', category:'content', title:'Create a content-calendar post', description:'Plan a post manually with its creative brief, channel and publishing time.', access:'Plan and edit content permission.', steps:['Open Content and choose Add post on the date you want to use.','Choose the platform and content format, and check the post date and time.','Fill in the content idea and relevant fields, including hook, objective, target audience, caption, creative direction, call to action and hashtags where shown.','Review platform-specific fields and any additional custom details before saving.','Save the post, then open its calendar card to check the brief and workflow stage.'], outcome:'The saved post is available to your team. It must pass internal review before appearing in the client portal.', note:'Saving a plan does not publish it. Approval, media, account access and publishing settings are separate requirements.', related:['edit-post','attach-creatives','internal-review','auto-publish'] },
  { id:'edit-post', category:'content', title:'Edit a post and its creative brief', description:'Update the words and instructions your team uses to produce content.', access:'Plan and edit content permission; approved content may be locked.', steps:['Open Content and select the post card.','Use the Content tab to review the brief and creative assets.','Use the edit controls provided for the post details or brief. Update the fields you need rather than replacing the entire plan.','Use Reimagine on an individual field where available if you want an AI-assisted alternative. Review its accuracy before keeping it.','Save your changes and reopen the post to confirm the saved version.'], outcome:'The team works from the updated brief.', troubleshooting:['Client-approved content is protected from ordinary editing. Check its review state and available return-to-review controls before making changes.','AI tools require the appropriate permission and available AI access.'], related:['attach-creatives','internal-review','generate-content'] },
  { id:'attach-creatives', category:'content', title:'Upload creative assets to a post', description:'Attach the actual images or videos your team will review and publish.', access:'Upload creatives permission; post must allow changes.', steps:['Open the post from Content.','In the Content tab, find the creative upload controls and select the files from your device.','Wait for the upload to complete. Keep the page open while progress is displayed.','Review the uploaded media in the post, including its order and platform suitability.','Ask an internal reviewer to review the final creative and caption together.'], outcome:'The post has media attached for review and, where supported, publishing.', note:'An attached file is not proof that a platform will accept it. Media format, duration and account-specific rules are checked separately.', related:['internal-review','publishing-status','edit-post'] },
  { id:'review-media', category:'content', title:'Inspect attached images, videos and timed feedback', description:'Check the creative itself rather than reviewing only the caption.', access:'View calendar permission; media must be attached to the post.', steps:['Open the post from Content and select the Content tab.','Choose an attached image or video using the media thumbnails when there are several assets.','Use the video player controls to inspect playback where applicable.','If timed video comments are present, select a comment timestamp to jump to that moment.','Use Internal review for private team feedback or Client review to read the client decision and feedback.'], outcome:'You can review the actual asset alongside the brief and relevant feedback.', note:'Viewing a media comment does not grant permission to write internal feedback or approve content. Those abilities are controlled separately.', related:['attach-creatives','internal-review','client-review'] },
  { id:'import-calendar', category:'content', title:'Import an existing content calendar', description:'Bring a prepared plan into Showwork and correct ambiguous entries before saving.', access:'Plan and edit content permission.', steps:['Open Content and select Import calendar.','Choose Browse files and select PDF, CSV, Excel, Word, TXT or HTML. The current importer accepts files up to 3 MB and up to 200 items. Wait for Showwork to open the file.','Review Import preferences: timezone, numeric date order, missing year, default time, default platform and time notation.','Check Column mappings. Keep useful custom fields and ignore columns that should not become content.','Review the content preview. Resolve entries needing attention, inspect duplicates, and select the posts to keep.','Select Import and wait for confirmation, then choose Go to calendar.'], outcome:'Only the selected, validated entries are added to the calendar.', troubleshooting:['Do not guess ambiguous dates: set the date order or correct the preview.','If confirmation fails, use Retry confirmation where offered and inspect the calendar before importing again.'], related:['create-post','content-stages','delete-reset'] },
  { id:'content-stages', category:'content', title:'Find posts by date, platform or workflow stage', description:'Focus the calendar on the work you need to do next.', access:'View calendar permission.', steps:['Open Content and move to the relevant calendar period.','Use the Internal review, Client review or Publishing stage controls to narrow the plan.','Combine the stage selection with available search, platform, content-type and category filters.','Select a post to inspect its delivery-style workflow and detailed status.','Clear the filters when you want the whole plan again.'], outcome:'You see the relevant posts without changing their actual workflow state.', note:'Approved means review approval. Scheduled and Published are separate publishing states.', related:['internal-review','client-review','publishing-status'] },
  { id:'preview-content', category:'content', title:'Preview content as a social feed', description:'Check how your planned posts read together before publishing.', access:'View calendar permission.', steps:['Open Content and find Calendar and channel previews.','Select Instagram, TikTok, LinkedIn, Facebook or X from the available preview tabs.','Review the planned posts, captions and creative assets in the selected feed layout.','Open an individual post when you need to inspect its brief or workflow.','Return to Calendar to continue planning.'], outcome:'You can assess your planned content as a feed rather than just a schedule.', note:'A preview is a planning aid, not a live provider feed or a guarantee of exactly how the final published post will render.', related:['attach-creatives','edit-post','publish-post'] },
  { id:'custom-post-details', category:'content', title:'Add custom details to a content plan', description:'Keep production information that does not fit the standard brief fields.', access:'Plan and edit content permission.', steps:['Open the Add post form and complete the required planning fields.','Find the custom-details area and select Add a custom detail.','Enter a clear label and value, such as a campaign reference or a production note.','Remove empty or unnecessary custom details before saving the post.','Open the saved post to review its additional details with the rest of the brief.'], outcome:'Your post carries the additional information the team needs.', note:'Custom fields are planning details. Do not assume they become a social caption, an automatic workflow action or a publishing instruction.', related:['create-post','edit-post','import-calendar'] },
  { id:'delete-reset', category:'content', title:'Delete a post or reset a content calendar', description:'Understand the difference between removing one post and clearing the plan.', access:'The relevant delete permission; Reset is owner-only.', steps:['For a single post, locate its card in Content and use Delete post. Read and confirm the deletion prompt.','For a full calendar reset, use Reset in the Content toolbar only if you intend to clear the plan.','Read the reset confirmation and complete the required confirmation before continuing.','After the action finishes, check the calendar and any affected publishing status.'], outcome:'The selected deletion or reset is applied, rather than merely hiding posts with filters.', note:'These are destructive actions. Keep a copy of information you need before confirming; do not use Reset to troubleshoot a filter or loading issue.', related:['content-stages','publishing-status','workspace-settings'] },
  { id:'internal-review', category:'review', title:'Give internal feedback and approve for client review', description:'Keep unfinished work private until an authorized reviewer clears it.', access:'Internal review permission. Owners always have it; managers have it by default unless changed.', steps:['Open the post from Content and select Internal review.','Review the brief, caption and attached media.','Enter Private team feedback and choose Share internal feedback if changes are needed.','When the content is ready, select Approve for client review.','Check that the stage now shows internal approval before asking the client to review.'], outcome:'Internally approved posts can appear in the unlocked client portal. Internal feedback stays private to the team.', note:'Internal feedback and approval notify the relevant workspace content team by email. Delivery depends on the email service; these messages are not sent to clients as internal feedback.', troubleshooting:['If feedback and approval controls are unavailable, ask the owner to check your Internal review permission in People.'], related:['client-review','team-permissions','client-portal'] },
  { id:'client-review', category:'review', title:'Get client approval or respond to revisions', description:'Share work after internal approval and follow the client decision.', access:'Client portal access for the client; relevant content permissions for the team.', steps:['Finish internal review for the post first.','Open Client to find the private client-view link and password. Share them with the intended reviewer.','The client opens the link, enters the password and selects an available post to review.','The client uses the review controls to approve the post or provide feedback and request a revision.','Back in the workspace, open the post’s Client review tab to read the decision and feedback. Update the work using the controls available for its state.','Check Publishing separately when approval is complete.'], outcome:'The client’s feedback or approval is recorded on the post.', note:'Before internal approval, the post is hidden from the client. Client approval alone does not guarantee that publishing is scheduled or successful.', related:['internal-review','auto-publish','publishing-status'] },
  { id:'reopen-internal-review', category:'review', title:'Return a post to internal review', description:'Bring work back into the private team workflow when it needs another check.', access:'Internal review permission; the post must allow reopening.', steps:['Open the post and choose Internal review.','Check its current internal and client approval states.','Use Return to internal review when the control is available.','Add clear private feedback explaining what needs to change.','Complete the internal review again before sending the updated work for client review.'], outcome:'The post returns to the internal workflow and must be cleared again before client review.', troubleshooting:['Client-approved content may be locked. If the control is unavailable, check the post’s protected state rather than deleting and recreating it.'], related:['internal-review','client-review'] },
  { id:'upload-knowledge', category:'knowledge', title:'Upload business documents', description:'Give content generation and customer replies a factual foundation.', access:'Manage business knowledge permission and available AI access.', steps:['Open Knowledge in AI Studio.','Select Upload documents and choose one or several PDF, Word, Excel, CSV or text files accepted by the uploader.','Wait for uploading and reading to finish. Follow any displayed size, format or extraction errors.','Check that each successful file appears in Documents & websites.','Review the source-derived business overview and the indexing status before generating new work.'], outcome:'Successfully processed sources are saved against this workspace and can inform its AI context.', note:'Reading a document and using it in a particular answer are different steps. AI retrieves relevant information within context limits; it does not paste every document into every request. Scanned or unreadable files may need a text-readable replacement.', related:['add-website','brand-personality','knowledge-maintenance','generate-content'] },
  { id:'add-website', category:'knowledge', title:'Add a website to Business Knowledge', description:'Read key public business pages without manually copying their content.', access:'Manage business knowledge permission and available AI access.', steps:['Open Knowledge and find Website address.','Enter the business website address and select Add website.','Wait while Showwork reads the site.','Check the saved website source and review the resulting business overview.','Upload a document for important details that the site cannot expose as readable text.'], outcome:'Readable website information becomes a workspace knowledge source.', note:'The current reader visits the homepage and up to four relevant pages, not the entire website. Login-only, blocked and JavaScript-only content may be unavailable.', related:['upload-knowledge','knowledge-maintenance','research-question'] },
  { id:'brand-personality', category:'knowledge', title:'Set your Brand Personality', description:'Tell AI what the brand represents, how it speaks and how people should feel.', access:'Manage business knowledge permission to update; knowledge viewers can read.', steps:['Open Knowledge and go to Brand Personality.','Answer each of the five single-choice questions about representation, personality, communication, audience feeling and content style.','Choose Other when you need a custom answer, then fill in the text field.','Select Save personality and wait for confirmation.','Revisit this section when the brand direction changes.'], outcome:'The saved identity can shape AI Studio content and customer replies for this workspace.', note:'Brand voice does not override facts, the customer’s intent or handoff and safety rules. If no personality is saved, existing generation continues normally.', related:['upload-knowledge','generate-content','ai-replies'] },
  { id:'knowledge-maintenance', category:'knowledge', title:'Keep knowledge accurate and remove outdated sources', description:'Maintain one reliable source library as your business changes.', access:'Manage business knowledge permission.', steps:['Open Knowledge and review Documents & websites, including source names and dates.','Upload updated documents or add the correct public website when offers, policies or prices change.','Use the remove control on a source you no longer want used and confirm removal.','Use Refresh overview from sources when you need to rebuild the overview from the current library.','Review the updated overview and source/index status before requesting new content or relying on AI replies.'], outcome:'Future AI work draws on the maintained workspace sources.', note:'Changing knowledge does not automatically rewrite existing posts, previously generated drafts or messages already sent.', related:['upload-knowledge','add-website','missing-information'] },
  { id:'generate-content', category:'ai', title:'Generate a content batch with AI Studio', description:'Turn a clear brief and business knowledge into editable draft content.', access:'Generate AI content permission, available AI allowance and required workspace access.', steps:['Add current business sources in Knowledge, then open Generate.','Choose a campaign objective, or let the strategy follow your business knowledge.','Set the date range, cadence, timezone and platform schedule using the available rhythm controls.','Select the platforms you want content for.','Use the creative-direction instructions to describe the audience need, campaign angle, priorities and exclusions. Review the batch summary.','Start generation and follow its progress. When drafts are ready, open the draft review before confirming content.'], outcome:'AI creates a draft batch for human review; it does not directly publish the content.', note:'AI requests consume your configured allowance. Generation time varies with batch size and service availability; there is no guaranteed instant completion.', troubleshooting:['If a request fails, check whether drafts already exist before retrying so you do not create another batch unnecessarily.'], related:['review-ai-drafts','missing-information','brand-personality','research-brief'] },
  { id:'review-ai-drafts', category:'ai', title:'Review, edit and confirm AI drafts', description:'Make generated content accurate and useful before moving it into the team workflow.', access:'Generate AI content and applicable content-editing access.', steps:['Open the draft review after generation, or resume the available saved-drafts review.','Move between drafts and check the idea, hook, objective, target audience, caption and creative direction.','Correct factual claims, pricing, dates, promises and any details that do not match your business knowledge.','Edit or remove drafts that are unsuitable. Confirm the drafts you want to keep using the provided confirmation controls.','Open Content and review the confirmed posts before producing assets and requesting internal approval.'], outcome:'Confirmed drafts move into normal content planning; internal and client approval still follow.', note:'Confirm all drafts is a bulk action. Read the batch first; confirmation is not the same as approval or publishing.', related:['generate-content','edit-post','internal-review'] },
  { id:'missing-information', category:'ai', title:'Answer AI clarification questions', description:'Supply important missing facts instead of asking AI to invent them.', access:'Generate AI content permission; saving lasting knowledge requires knowledge-management access.', steps:['Read any clarification request shown during generation.','Enter specific factual answers in the fields provided, such as the intended audience, offer or campaign goal.','If you want to reuse the answers and have permission, select Save answers to business knowledge and wait for confirmation.','Select Use answers for this request, or Continue without unresolved details when you want unsupported details omitted. If sources are still processing, you can wait and retry instead.','For facts that should be reused, also maintain an authoritative source in Knowledge.'], outcome:'The current brief has better factual context for generation.', note:'Do not assume that every message or one-off instruction becomes permanent knowledge. Check the save confirmation and your source library.', related:['generate-content','upload-knowledge','knowledge-maintenance'] },
  { id:'research-question', category:'research', title:'Chat and research with Randy', description:'Talk about your business, explore sourced ideas and propose additions to Business Knowledge.', access:'Knowledge view permission to read your conversations; AI generation permission and active workspace to chat. Knowledge management permission to research or confirm additions.', steps:['Open Randy in AI Studio. Select Start conversation or choose one of your saved conversations.','Ask about your business, audience, brand or known rules. Randy uses relevant Business Knowledge passages and recent conversation; it may ask for missing details.','To investigate online, ask Randy to research a specific question. Review the proposed public research topic, then select Start research. Keep private customer details out of the topic.','Read the findings in the conversation and expand Sources to inspect supporting evidence. Continue asking follow-up questions in the same conversation.','Randy may offer a useful knowledge addition, or you can ask for one. Review the proposed addition and select Confirm & save if accurate. It adds a shared source; existing conflicting documents are not overwritten.','To create content from the discussion, select Create content prompt or ask Randy. Review the prompt in chat, then Copy prompt or Use in Generate.'], outcome:'Your conversation is saved privately to your login within this workspace. Confirmed additions become shared Business Knowledge sources.', note:'Randy does not read every document in every reply: it retrieves relevant passages. Research is external evidence, not company policy. Nothing is saved to knowledge without confirmation. No content is automatically generated or published.', related:['research-feedback','research-brief','add-website'] },
  { id:'research-feedback', category:'research', title:'Check research evidence in your conversation', description:'Inspect sources, discuss uncertainty and challenge findings without leaving Randy.', access:'Knowledge view to read your own conversations; AI generation permission to continue chatting.', steps:['Open Randy and choose the conversation containing your research.','Expand Sources beneath the answer and open supporting links to inspect the evidence.','Ask Randy which parts are verified, uncertain or proposed experiments, and explain any incorrect assumptions.','Ask a follow-up question or request more research when the evidence is insufficient.','Review any proposed knowledge addition separately. Nothing is saved as business information until an authorized member confirms it.'], outcome:'Research can inform your discussion while keeping uncertainty visible.', note:'Chat feedback does not automatically edit or delete historical research records or retract existing generated content. External research must not be treated as proof of company prices, policies or capabilities.', related:['research-question','research-brief','knowledge-maintenance'] },
  { id:'research-brief', category:'research', title:'Turn a Randy conversation into a content prompt', description:'Prepare a generation prompt directly from your business discussion and research.', access:'AI generation permission to prepare a prompt and use Generate.', steps:['Discuss the idea or research findings with Randy in the same conversation.','Ask to create content from the discussion, or select Create content prompt below the latest answer.','Review the content prompt Randy prepares. Edit the prompt in its card to refine the objective, audience, angle and creative direction.','Select Copy prompt to copy the text, or Use in Generate to open Generate with the instructions filled in.','Review your platforms, dates and other generation settings, then start generation when ready.'], outcome:'A reviewed prompt carries your discussion into AI content generation.', note:'Use in Generate does not automatically generate, approve or publish posts. Knowledge additions are separate and require confirmation.', related:['generate-content','research-feedback','review-ai-drafts'] },
  { id:'connect-instagram', category:'channels', title:'Connect Instagram and select the correct account', description:'Authorize the Facebook Page and linked professional Instagram account for this workspace.', access:'Manage channel connections permission and access to the intended Meta assets.', steps:['Open Channels and select Connect Instagram, or its reconnect control.','Complete Meta login using the account with access to the intended Facebook Page and Instagram professional account.','Review the requested permissions and allow access to the correct assets.','Back in Showwork, select the returned Facebook Page and linked Instagram account, then confirm the connection.','Check the connected account name and the capability or reauthorization notices in Channels.'], outcome:'The selected Instagram account is associated with this workspace.', troubleshooting:['If no linked account is returned, retry authorization with the appropriate Page selected. A successful Meta login does not by itself prove Showwork received that asset.','Insights permission is separate from basic connection, publishing and messaging. Follow the specific access notice rather than disconnecting other working channels.'], related:['connect-other-channels','channel-capabilities','report-missing-data'] },
  { id:'connect-tiktok', category:'channels', title:'Connect or reconnect TikTok', description:'Authorize your TikTok account and review the access it actually grants.', access:'Manage channel connections permission.', steps:['Open Channels and choose Connect TikTok or Reconnect TikTok.','Sign in to the intended TikTok account and review the requested permissions.','Authorize and return to Showwork.','Check the account name and any missing publishing or analytics access notices.','If you need TikTok Business Messaging, use its separate connection controls and setup instructions; ordinary publishing authorization does not enable DMs.'], outcome:'The authorized account is connected with the permissions granted by TikTok.', troubleshooting:['A newly approved provider permission may require a fresh reconnection. Reconnecting only helps if the deployed application requests that permission.'], related:['tiktok-publish','channel-capabilities','report-missing-data'] },
  { id:'connect-other-channels', category:'channels', title:'Connect Facebook, LinkedIn, X or WhatsApp', description:'Add the channels your workspace needs without confusing publishing with messaging.', access:'Manage channel connections permission and the provider’s required account access.', steps:['Open Channels and find the platform card.','Read its capability description before choosing the connection action.','Complete that provider’s authorization or the configuration steps shown for that channel. For Facebook and LinkedIn, choose the intended Page or account when prompted.','Return to Showwork and verify the connected identity and access notices.','Complete any separate messaging setup shown before expecting conversations in Inbox.'], outcome:'Supported connections are linked to this workspace with their actual granted access.', note:'WhatsApp is for supported messaging, leads and AI replies; it is not a social-post publishing or analytics connection. Provider approvals, account eligibility and configured webhooks can affect availability.', related:['channel-capabilities','inbox-conversation','connect-instagram'] },
  { id:'channel-capabilities', category:'channels', title:'Check access, reconnect or disconnect a channel', description:'Understand why a connected account may not support every action.', access:'View channels; manage channels to reconnect or disconnect.', steps:['Open Channels and check the platform card, connected identity and any access warning.','Distinguish publishing, analytics and messaging: each can require different permissions or configuration.','Use reconnect when a token has expired or a newly available permission needs authorization.','In Inbox, open Channel access to read messaging availability for each account.','Disconnect only when you intend to remove that connection; check scheduled posts before doing so.'], outcome:'You can identify the missing capability and take the relevant action.', note:'A Connected badge does not guarantee that every API operation is available. Always check the feature-specific status.', related:['publishing-status','report-missing-data','inbox-reply-unavailable'] },
  { id:'auto-publish', category:'publishing', title:'Turn automatic publishing on or off', description:'Choose whether new client approvals should enter the publishing queue.', access:'Publishing-management permission.', steps:['Open Content and locate Auto-publish approved posts.','Read the current On or Off state and open How publishing works if needed.','Use the switch and wait for the setting to save.','With it on, new client approvals can be queued for their calendar time on supported connected channels when all requirements are met.','With it off, client approval stays an approval; scheduled posts are paused according to the setting.'], outcome:'The workspace uses your chosen automatic-publishing behaviour.', note:'Turning it on does not queue posts approved while it was off. Deliveries already started may finish. TikTok also needs per-post settings and consent.', related:['client-review','tiktok-publish','publishing-status'] },
  { id:'publish-post', category:'publishing', title:'Schedule or publish an approved post', description:'Check the final requirements and use the available publishing controls.', access:'Publishing-management permission and the correct connected channel.', steps:['Open the post and confirm both internal and client approval are complete.','Check the attached media, caption, selected account and scheduled date/time.','Open Publishing in the post details.','Use the scheduling or publish-now action offered for that platform, completing any additional settings or authorization.','Watch the publishing state and inspect the result or error after processing.'], outcome:'The post is scheduled or submitted to the provider; Published is shown only after the publishing flow confirms it.', note:'Scheduling is not proof of delivery. Provider validation, expired tokens, rate limits and media restrictions can stop a post.', related:['auto-publish','tiktok-publish','publishing-status'] },
  { id:'tiktok-publish', category:'publishing', title:'Authorize a TikTok post for publishing', description:'Set visibility and consent for each TikTok post.', access:'Publishing-management permission, TikTok connection and both review approvals.', steps:['Open the post’s Publishing tab and review TikTok settings.','Choose an available privacy level and review the account-specific media and interaction options.','Set commercial-content disclosures and AI-generated-media labels accurately when applicable.','After approval, review TikTok’s displayed terms and give publishing consent.','Select Authorize and schedule or Authorize and publish now.','For a failed attempt, check TikTok first and use the confirmation and retry controls only if it did not publish.'], outcome:'The specific post has the required authorization for the selected publishing action.', note:'TikTok’s available privacy levels and publishing eligibility come from the connected account and application access; they are not guaranteed by a connection badge.', related:['connect-tiktok','auto-publish','publishing-status'] },
  { id:'publishing-status', category:'publishing', title:'Understand Approved, Scheduled, Published and Failed', description:'Separate review decisions from actual social-platform delivery.', access:'View calendar; publishing access for corrective actions.', steps:['Open the post and inspect its workflow and Publishing tab.','If it is pending internal review, complete that review before requesting client approval.','If it is Approved, check auto-publishing, channel access, media requirements and any per-post authorization.','If it is Scheduled, check the scheduled time and allow the worker/provider to process it.','If it is Failed, read the error, check the provider for an existing post, correct the issue and use an offered retry action.'], outcome:'You know which requirement or publishing stage needs attention.', troubleshooting:['Do not repeatedly retry or recreate a post without checking the provider; a delayed confirmation can otherwise lead to duplicates.','A disconnected or expired account must be restored before the next publishing attempt.'], related:['publish-post','channel-capabilities','auto-publish'] },
  { id:'inbox-conversation', category:'inbox', title:'Find a conversation and send a reply', description:'Use one inbox for supported connected messaging channels.', access:'Read messages; reply permission and channel messaging access to send.', steps:['Open Inbox and choose All conversations or a platform filter.','Search for a person or message, and optionally filter by unread status or lead stage. On mobile, open the tools control for extra filters.','Select a person. On mobile, this opens the chat; use Back to conversations to return to the list.','Read the history, enter your reply and select Send.','On desktop, use Expand conversation view for more message space; use Back to inbox tools to leave it.'], outcome:'The reply is sent through the selected channel when its rules and connection permit it.', note:'Sent, Delivered and Read depend on the provider. A disabled Send button should be investigated using the displayed availability message.', related:['inbox-reply-unavailable','ai-replies','human-handoff','x-messages'] },
  { id:'ai-replies', category:'inbox', title:'Set up AI replies and use reply suggestions', description:'Apply your business knowledge and brand voice to customer conversations.', access:'Inbox management for setup; reply access for drafts; the relevant AI feature must be available.', steps:['Add accurate sources and Brand Personality in Knowledge first.','In Inbox, open AI & inbox setup.','Choose the reply tone, enter appropriate handoff guidance and turn Automatic AI replies on only when you want them enabled. Wait for settings to save.','For a manual suggestion, open a conversation and expand AI reply assistant.','Select a tone, add context for that reply if needed, and choose Draft reply. Review the suggestion, use it in the composer and select Send when ready.'], outcome:'Automatic replies can process eligible new messages; suggestions remain drafts until you use and send them.', note:'AI suggestions can be wrong. Brand voice must not override factual knowledge or sensitive-customer handling. Encrypted X history is excluded from shared AI context.', related:['human-handoff','brand-personality','upload-knowledge'] },
  { id:'human-handoff', category:'inbox', title:'Take over a conversation or resume AI', description:'Move a sensitive or high-intent conversation to a person without a banner covering the chat.', access:'Reply permission for the workspace conversation; not available for encrypted X conversations.', steps:['Open Inbox and use Needs attention when a conversation is waiting for a person.','Open the conversation, then select AI on, AI off or AI paused in its header.','Read the handoff reason. Select Take over to acknowledge human handling and pause automatic replies.','Continue the conversation manually, checking the customer’s request and channel reply window.','When it is appropriate to return control, open the same menu and choose Resume AI. Close the controls to return to the chat.'], outcome:'The conversation’s AI-control state records whether a person or AI should continue.', note:'AI can hand off for human requests, buying/payment intent, complaints, uncertainty or sensitive topics. Handoff alerts appear in Showwork and email the owner and responsible inbox teammates, with social-media-manager fallback when no responsible teammate is found. Email delivery is not an instant-response guarantee.', related:['ai-replies','inbox-conversation','team-permissions'] },
  { id:'x-messages', category:'inbox', title:'Unlock encrypted X messages', description:'Keep X Chat access separate from your normal conversation list.', access:'Workspace owner with a supported connected X account and the existing X Chat PIN.', steps:['Open Inbox. On desktop, find Encrypted X messages beside the channel filters. On mobile, open Inbox tools first.','Expand the Encrypted X messages dropdown and choose Unlock X messages.','Follow the access check, then enter your existing X Chat PIN where requested.','Open the unlocked X conversation from the inbox. Use the X refresh or older-message controls when needed.','Use Lock when you want to clear the unlocked session.'], outcome:'Supported encrypted conversations can be read and replied to on this device.', note:'The PIN stays on the device. Encrypted conversations are excluded from shared history and AI. Closing the dropdown alone does not lock the session.', related:['inbox-conversation','inbox-reply-unavailable'] },
  { id:'inbox-reply-unavailable', category:'inbox', title:'Troubleshoot missing messages or unavailable replies', description:'Check the actual connection, permissions and provider reply rules.', access:'Read messages; channel managers may need to fix access.', steps:['Check the channel filter, search, unread filter and lead-status filter before assuming a message is missing.','Open Channel access and read the messaging status for the intended account.','Ask a channel manager to check the connection and any reauthorization or messaging setup notice in Channels.','Read the composer’s availability message and any send error. A provider reply window may require the customer to message again.','Refresh the inbox after correcting access, and verify the provider conversation before retrying a failed send.'], outcome:'You can distinguish a filter issue from missing permission, provider restrictions or incomplete messaging setup.', note:'Connecting a publishing account does not automatically provide messaging access. Imported conversation history does not necessarily trigger automatic replies.', related:['channel-capabilities','inbox-conversation','ai-replies'] },
  { id:'create-lead', category:'leads', title:'Add and qualify a lead', description:'Keep contact details and follow-up context in a clear relationship pipeline.', access:'View leads; manage leads to create or edit.', steps:['Open Leads and select Add lead.','Enter the name and any known username, email, phone and company.','Choose Hot, Warm or Cold to describe opportunity temperature.','Set the pipeline stage: New, Contacted, Qualified, Customer or Lost. Add useful notes.','Save, then use Edit on the lead when new information arrives.'], outcome:'The contact is recorded in this workspace with a qualification stage and follow-up details.', note:'Lead notes are not a scheduled reminder or an automated follow-up. Contact the person through an available channel and maintain the record as the relationship changes.', related:['lead-filters','lead-csv','inbox-conversation'] },
  { id:'lead-filters', category:'leads', title:'Filter leads and track the pipeline', description:'Focus on the contacts that need your attention.', access:'View leads permission.', steps:['Open Leads and inspect Active leads, Hot opportunities, Converted customers and Lead conversion.','Choose a stage shortcut such as Contacted or Qualified.','Combine it with search and the temperature filter to narrow the list.','Use the pagination and Per page control for larger lists. On mobile, read the labelled contact cards.','Edit the record when a customer’s stage changes, if your role permits it.'], outcome:'You can focus follow-up work without changing records merely by filtering.', note:'The conversion metric describes the stored lead records, not an attributed revenue or advertising conversion report.', related:['create-lead','lead-csv','reporting-leads'] },
  { id:'lead-csv', category:'leads', title:'Import or export leads as CSV', description:'Bring contacts into the workspace or download a filtered list.', access:'Manage leads to import; view leads for the available export action.', steps:['Open Leads and choose Import CSV if you have management access.','Choose a CSV under 2 MB with up to 500 leads. Include a Name or Full Name header; optional columns include Username, Email, Phone, Company, Temperature, Status and Notes.','Read the import result, including the number created and any duplicates skipped.','For export, set the search, stage and temperature filters you want first.','Select Export CSV to download the leads matching those filters, across the filtered list rather than only the visible page.'], outcome:'Your import result is confirmed or the filtered contact list is downloaded.', note:'CSV files contain personal contact data. Share exports only with people who should have that information.', troubleshooting:['Correct format or validation errors before retrying. Check the imported list first so you do not import the same contacts again unnecessarily.'], related:['create-lead','lead-filters'] },
  { id:'report-filters', category:'analytics', title:'View analytics for selected platforms', description:'Combine two or more platforms without including channels you did not select.', access:'View analytics permission; some metrics require advanced analytics access.', steps:['Open Analytics & Reporting and choose the From and To dates.','Select the platform buttons you want, such as Instagram and TikTok.','Select Apply platforms to activate the selection. Until then, the current report remains visible.','Use the quick date ranges or report-section links to explore performance, opportunities, recommendations and channel content.','Use Reset to return to the default dates and all platforms.'], outcome:'The report queries the applied platforms and selected reporting period.', note:'The content-pipeline cards at the bottom are explicitly workspace-wide: all dates and platforms. They are separate from the performance filters above.', related:['report-sync','report-missing-data','reporting-leads'] },
  { id:'report-sync', category:'analytics', title:'Refresh a report or sync social data', description:'Understand the difference between loading saved metrics and requesting a new provider sync.', access:'View analytics to refresh; manage analytics to sync supported accounts.', steps:['Open Analytics & Reporting and apply your desired platforms and dates.','Use Refresh to reload the saved report for those filters.','Use Sync data when available to start a sync for supported connected accounts.','Wait for the sync notice and completion, then inspect the refreshed report and account timestamps.','Read the labels for each metric: period totals, rolling totals and lifetime post counters describe different measurements.'], outcome:'You see the latest available saved/provider data, with its measurement basis.', note:'Sync support varies by platform. The current manual sync action targets supported connected Instagram, TikTok and Facebook accounts; it does not promise every channel supports the same metrics.', related:['report-filters','report-missing-data','report-insights'] },
  { id:'report-missing-data', category:'analytics', title:'Understand missing metrics and analytics access', description:'Know why a value shows a dash instead of a number.', access:'View analytics; channel managers may need to reconnect accounts.', steps:['Read the metric label, basis and explanatory note. A dash means unavailable, not zero.','Check the connected account’s sync time and any visible error.','Open Channels to inspect analytics access. Reconnect if the provider needs fresh authorization for insights or video/account statistics.','Confirm the intended professional account or Page is selected and supports the requested metric.','Sync again when available and check the result. If it still fails, share the visible error and account name with support without sharing tokens.'], outcome:'You can identify whether missing data comes from access, coverage, provider support or a sync problem.', note:'Different platforms expose different metrics. Saves, shares, reach and views must not be invented or treated as zero when unavailable.', related:['report-sync','connect-instagram','connect-tiktok'] },
  { id:'report-insights', category:'analytics', title:'Use AI reporting recommendations', description:'Move from performance evidence to a deliberate content experiment.', access:'Manage analytics and performance-recommendation access; generating content needs AI/content access.', steps:['Open Analytics & Reporting and select the report filters you intend to analyze.','Open AI action studio and read the available findings and evidence.','Use Refresh AI analysis when you want a new analysis and have the required allowance.','Filter findings by wins, improvements, trends or next actions.','Use Create content from this insight or Apply all recommendations to carry the selected direction into Generate.','Review the campaign settings and brief before starting a content batch.'], outcome:'Observed performance informs a new brief; content is not automatically generated or published merely by applying recommendations.', note:'AI analysis can consume allowance and is not proof of causation. Validate suggestions against business knowledge and actual customer needs.', related:['generate-content','report-filters','research-brief'] },
  { id:'reporting-leads', category:'analytics', title:'Read lead opportunities and production summaries', description:'Distinguish social performance, the CRM pipeline and workspace planning health.', access:'View analytics; private lead opportunities also require view-leads access.', steps:['Open Analytics & Reporting and read the lead-opportunity section if your role permits it.','Review hot open leads and use Open leads to continue qualification in the lead list.','At the bottom, inspect the channel-distribution chart for the workspace’s planned content mix.','Review the production-stage breakdown: AI drafts, internal review, changes needed, client review, approved and published.','Use creative-asset counts to identify posts without attached media, then open Content to prepare them.'], outcome:'You know which relationships and production tasks need attention alongside social performance.', note:'Private lead details are excluded from shared client reporting. Production summaries cover the entire workspace, independently of the performance report filters.', related:['lead-filters','content-stages','report-filters'] },
  { id:'invite-teammate', category:'people', title:'Invite a teammate and choose their role', description:'Grant the right access before someone joins the workspace.', access:'Manage teammates permission; only the owner can appoint managers.', steps:['Open People and select Invite teammate.','Enter the teammate’s email address.','Choose Manager, Social Media Manager, Creative Contributor, Inbox Agent or Viewer as allowed by your account and plan. Read the role description.','Review Feature access. Adjust individual permissions if your subscription and delegation rights allow it.','Select Send invitation and check its delivery status in Invitations.'], outcome:'The recipient receives an invitation for this workspace with the chosen role and access.', note:'Workspace memberships and active invitations can use team allowance across owned workspaces. A manager cannot delegate permissions they do not have.', related:['team-permissions','manage-team','internal-review'] },
  { id:'team-permissions', category:'people', title:'Grant internal review or customize feature access', description:'Control who can approve content, reply to messages or manage tools.', access:'Manage teammates permission, delegation rights and custom-feature access where required.', steps:['Open People and choose Edit access for the relevant teammate, or configure a new invitation.','Choose the intended role before refining Feature access.','Enable Internal review if the person should give private feedback and approve content for client review.','Review related permissions for content, publishing, customer care, knowledge and administration.','Save access and ask the teammate to refresh their workspace.'], outcome:'The teammate has the saved permissions, subject to role and delegation rules.', note:'Owners always retain internal review. Managers have it by default but it can be removed. Eligible other roles can receive it; Viewer cannot. Creative upload, publishing, inbox replies and team management are separate permissions.', related:['invite-teammate','manage-team','human-handoff'] },
  { id:'manage-team', category:'people', title:'Resend invitations, remove access and inspect activity', description:'Keep workspace membership current without deleting someone’s Showwork account.', access:'People view for the list/history; management access for permitted changes.', steps:['Open People and search by name, email or role.','Expand a member’s access summary to inspect individual permissions.','In Invitations, check delivery or expiry status. Use Resend where allowed, or Cancel to invalidate an unwanted invitation.','To remove a teammate, select Remove, read the confirmation and confirm only if their access should end.','Open Team activity to review invitations, access changes and removals. Use pagination for earlier events.'], outcome:'Membership and invitation records reflect the people who should have access.', note:'Removing a teammate affects this workspace; it does not delete their account or their access to other workspaces. Ownership and billing remain with the owner.', related:['invite-teammate','team-permissions'] },
  { id:'client-portal', category:'settings', title:'Share the private client portal', description:'Let a client review approved internal work without exposing the production workspace.', access:'Client-view access; workspace-management permission for password changes.', steps:['Open Client in the workspace menu, or use Client view in the header to preview the portal.','Copy the private client-view address from the Client section.','Find the private workspace password under Access credentials. Use the available password controls if you need to manage it.','Share the link and password only with the intended client reviewers.','Make sure posts are internally approved before expecting them to appear in the client view.'], outcome:'The client can unlock the separate portal and review available work.', note:'The portal password does not make the client a workspace team member. Internal feedback remains private. Inbox visibility is controlled separately in AI & inbox setup.', related:['client-review','client-inbox','workspace-settings'] },
  { id:'client-password', category:'settings', title:'Copy or change the client portal password', description:'Manage the credential used to unlock this workspace’s client view.', access:'Client credentials visible to your role; workspace-management permission to change them.', steps:['Open Client and find Private workspace password under Access credentials.','Use Copy to copy the current password when sharing it with an intended reviewer.','To update it, select Change password if the control is available.','Enter a custom password and select Set, or choose Or generate a random one instead. Wait for the update to finish.','Share the current password through an appropriate private channel and check the client-view login if needed.'], outcome:'You have copied the current credential or saved a replacement password.', note:'Treat the password and review link as private. Changing a password is not the same as removing a team member; do not assume it immediately revokes every already-unlocked browser session.', related:['client-portal','client-review','manage-team'] },
  { id:'client-inbox', category:'settings', title:'Choose whether the client can read the inbox', description:'Control conversation visibility in the private client portal.', access:'Inbox settings management and applicable inbox access.', steps:['Open Inbox, then AI & inbox setup.','Find Client visibility.','Turn Allow client inbox access on or off and wait for the setting to save.','Preview the client portal to check the experience available to the reviewer.'], outcome:'The client’s inbox visibility follows the saved setting.', note:'Client access is read-only for conversations; it does not grant workspace reply or team-management permissions. Encrypted X history is not shared.', related:['client-portal','ai-replies','team-permissions'] },
  { id:'workspace-settings', category:'settings', title:'Rename, manage or delete a workspace', description:'Use workspace settings deliberately and understand protected owner actions.', access:'Relevant workspace-management or ownership permissions; controls vary by role.', steps:['Open Settings from the blue workspace header.','To rename, choose Rename workspace, enter the new client name and save it.','For subscription and team allowance, open the appropriate Billing link from the dashboard or People allowance section.','If you intend to delete the workspace, choose Delete workspace only when available to your role.','Read the permanent-deletion warning and complete the required confirmation.'], outcome:'The selected setting is updated, or the confirmed destructive action is applied.', note:'Deleting a workspace is different from removing a teammate or resetting calendar posts. Do not delete a workspace as a way to clear a filter, refresh analytics or reconnect a channel.', related:['delete-reset','manage-team','client-portal'] },
];
export function searchWorkspaceGuides(query: string, category = 'all') {
  const terms = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
  return workspaceGuides.filter(guide => (category === 'all' || guide.category === category) && terms.every(term => [guide.title,guide.description,guide.access,...guide.steps,guide.note || '',...(guide.troubleshooting || [])].join(' ').toLowerCase().includes(term)));
}
